// Some portions generated by Codex
import assert from "node:assert/strict";
import test, { before, after } from "node:test";
import { createServer } from "vite";
import { createElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";

let server;
let CollectionDetails;
before(async () => {
  server = await createServer({ server: { middlewareMode: true }, optimizeDeps: { noDiscovery: true } });
  ({ CollectionDetails } = await server.ssrLoadModule("/graph-explorer/collection-details.tsx"));
});
after(async () => { await server?.close(); });

const actions = {
  onToggleStructure() {}, onToggleConnections() {}, onLoad() {}, onMember() {}, onCell() {},
};
const render = (props) => renderToStaticMarkup(createElement(CollectionDetails, {
  nodes: new Map(), expanded: false, connected: false, loading: false, canLoad: false,
  ...actions, ...props,
}));

test("the rendered inspector bounds a 50,000-member list and preserves repeated positions", () => {
  const count = 50_000;
  const cells = new Map(Array.from({ length: count }, (_, i) => [`urn:cell:${i}`, {
    id: `urn:cell:${i}`, memberId: "urn:member",
    nextId: i + 1 < count ? `urn:cell:${i + 1}` : "http://www.w3.org/1999/02/22-rdf-syntax-ns#nil",
    firstEdgeIds: [], restEdgeIds: [], hasStructure: true,
  }]));
  const info = { headId: "urn:cell:0", status: "complete", count, loadedCount: count, collapsible: true };
  const analysis = {
    cells, heads: new Set([info.headId]), collections: new Map([
      [info.headId, info],
      ["urn:cell:1", { ...info, headId: "urn:cell:1", count: count - 1, loadedCount: count - 1 }],
    ]),
  };
  const props = {
    analysis, headId: info.headId,
    nodes: new Map([["urn:member", { id: "urn:member", label: "A & <B>", kind: "literal", language: "en" }]]),
  };
  const html = render(props);
  const mounted = (html.match(/class="collection-details-row"/g) ?? []).length;
  assert.ok(mounted > 0 && mounted <= 11, `${mounted} mounted rows`);
  assert.match(html, /50,000/);
  assert.match(html, /Select member 1: A &amp; &lt;B&gt;/);
  assert.match(html, /Select member 2: A &amp; &lt;B&gt;/);
  assert.match(html, /Inspect cell 2/);
  assert.match(html, /@en/);
  assert.match(html, /Show RDF structure/);
  assert.match(html, /Only loaded statements were checked/);
  const suffix = render({ ...props, headId: "urn:cell:1" });
  assert.doesNotMatch(suffix, /Show RDF structure|Show member connections/);
});

test("the inspector explains why a continuation is unavailable and keeps its action disabled", () => {
  const headId = "urn:partial";
  const info = { headId, status: "partial", count: null, loadedCount: 0, collapsible: false, reason: "The next member is not loaded." };
  const analysis = { cells: new Map(), heads: new Set([headId]), collections: new Map([[headId, info]]) };
  const html = render({ analysis, headId, continuationUnavailableReason: "No new statements were returned." });
  assert.match(html, /Incomplete in this view/);
  assert.match(html, /disabled="">Load continuation/);
  assert.match(html, /No new statements were returned/);
  assert.doesNotMatch(html, /no reusable repository identifier/);
});
